package com.ghordrin.bosshealthbar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class KnownBossesTest
{
	@Test
	public void matchesListedBossesIgnoringCase()
	{
		assertTrue(KnownBosses.contains("Zulrah"));
		assertTrue(KnownBosses.contains("zulrah"));
		assertTrue(KnownBosses.contains("K'RIL TSUTSAROTH"));
	}

	@Test
	public void rejectsOtherNamesAndNull()
	{
		assertFalse(KnownBosses.contains("Mithril dragon"));
		assertFalse(KnownBosses.contains(""));
		assertFalse(KnownBosses.contains(null));
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.DamageTracker.COMBO_WINDOW;
import static com.ghordrin.bosshealthbar.DamageTracker.nextComboDamage;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class DamageTrackerTest
{
	private static final long WINDOW_MILLIS = COMBO_WINDOW.toMillis();

	@Test
	public void firstHitStartsTheCombo()
	{
		assertEquals(50, nextComboDamage(0, 0, 1_000, 50));
	}

	@Test
	public void hitsWithinTheWindowAddUp()
	{
		final int afterFirstHit = nextComboDamage(0, 0, 1_000, 50);
		final int afterSecondHit = nextComboDamage(afterFirstHit, 1_000, 1_000 + WINDOW_MILLIS - 1, 30);

		assertEquals(80, afterSecondHit);
	}

	@Test
	public void aHitRightAtTheWindowEdgeStillCounts()
	{
		assertEquals(80, nextComboDamage(50, 1_000, 1_000 + WINDOW_MILLIS, 30));
	}

	@Test
	public void aHitPastTheWindowStartsAFreshCombo()
	{
		assertEquals(30, nextComboDamage(50, 1_000, 1_000 + WINDOW_MILLIS + 1, 30));
	}

	@Test
	public void aStalePreviousComboIsIgnoredWhenThereWasNoRecentHit()
	{
		assertEquals(10, nextComboDamage(999, 0, 5_000, 10));
	}
}

package com.ghordrin.bosshealthbar;

import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
class GameBossBar
{
	// Set to 1 on NPCs whose game boss bar only shows a percentage. No gameval constant exists for it.
	private static final int PARAM_HP_PERCENTAGE_ONLY = 2289;

	private static final int[] PHASE_MARKER_VARBITS = {
		VarbitID.HPBAR_HUD_LOWER_THRESHOLD,
		VarbitID.HPBAR_HUD_UPPER_THRESHOLD,
		VarbitID.HPBAR_HUD_HP_1,
		VarbitID.HPBAR_HUD_HP_2,
	};

	private final Client client;

	private boolean hidden;
	private NPC npc;
	private int searchedId = -1;
	private int replacedId = -1;

	private int percentOnlyNpcId = -1;
	private boolean percentOnly;

	private final int[] phaseMarkerValues = new int[PHASE_MARKER_VARBITS.length];
	private int phaseMarkerMaxHealth;
	private float[] phaseMarkers = BarState.NO_PHASE_MARKERS;

	@Inject
	GameBossBar(Client client)
	{
		this.client = client;
	}

	int trackedNpcId()
	{
		if (client.getVarbitValue(VarbitID.HPBAR_HUD_BOSS_DISABLED) != 0)
		{
			return -1;
		}
		return client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
	}

	boolean isTracking(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return false;
		}
		final int trackedId = trackedNpcId();
		return trackedId != -1 && NpcUtil.baseId((NPC) actor) == trackedId;
	}

	NPC findNpc(Actor opponent)
	{
		final int trackedId = trackedNpcId();
		if (trackedId == -1)
		{
			npc = null;
			searchedId = -1;
			return null;
		}

		if (isTracking(opponent))
		{
			npc = (NPC) opponent;
			return npc;
		}

		final Player player = client.getLocalPlayer();
		final Actor target = player != null ? player.getInteracting() : null;
		if (isTracking(target))
		{
			npc = (NPC) target;
			return npc;
		}

		if (npc != null && NpcUtil.baseId(npc) == trackedId)
		{
			return npc;
		}

		if (npc == null && trackedId == searchedId)
		{
			return null;
		}

		npc = null;
		searchedId = trackedId;
		for (NPC candidate : client.getTopLevelWorldView().npcs())
		{
			if (NpcUtil.baseId(candidate) == trackedId)
			{
				npc = candidate;
				break;
			}
		}
		return npc;
	}

	void onNpcSpawned()
	{
		searchedId = -1;
	}

	void onNpcDespawned(NPC despawned)
	{
		if (despawned == npc)
		{
			npc = null;
		}
	}

	void update(Actor opponent, boolean replaceEnabled, boolean opponentGetsBar)
	{
		final Widget bar = client.getWidget(InterfaceID.HpbarHud.UNIVERSE);
		if (bar == null)
		{
			hidden = false;
			return;
		}

		boolean replace = false;
		if (replaceEnabled)
		{
			if (opponentGetsBar && isTracking(opponent))
			{
				replace = true;
				replacedId = trackedNpcId();
			}
			else
			{
				// After the boss despawns, the game's bar can stay up on it while the defeat animation
				// plays, so keep it hidden until it tracks a different NPC.
				replace = replacedId != -1 && trackedNpcId() == replacedId;
			}
		}

		if (replace)
		{
			if (!bar.isSelfHidden())
			{
				bar.setHidden(true);
				hidden = true;
			}
		}
		else
		{
			replacedId = -1;
			restore();
		}
	}

	void restore()
	{
		if (!hidden || trackedNpcId() == -1)
		{
			return;
		}

		final Widget bar = client.getWidget(InterfaceID.HpbarHud.UNIVERSE);
		if (bar != null)
		{
			bar.setHidden(false);
		}
		hidden = false;
	}

	void reset()
	{
		hidden = false;
		npc = null;
		searchedId = -1;
		replacedId = -1;
	}

	int maxHealth()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP);
	}

	int health()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
	}

	boolean isPercentOnly()
	{
		final int npcId = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
		if (npcId != percentOnlyNpcId)
		{
			final NPCComposition composition = npcId != -1 ? client.getNpcDefinition(npcId) : null;
			percentOnly = composition != null && composition.getIntValue(PARAM_HP_PERCENTAGE_ONLY) == 1;
			percentOnlyNpcId = npcId;
		}
		return percentOnly;
	}

	float[] phaseMarkers(int maxHealth)
	{
		boolean changed = maxHealth != phaseMarkerMaxHealth;
		for (int i = 0; i < PHASE_MARKER_VARBITS.length; i++)
		{
			final int value = client.getVarbitValue(PHASE_MARKER_VARBITS[i]);
			if (value != phaseMarkerValues[i])
			{
				phaseMarkerValues[i] = value;
				changed = true;
			}
		}
		if (!changed)
		{
			return phaseMarkers;
		}
		phaseMarkerMaxHealth = maxHealth;

		float[] markers = null;
		int count = 0;
		for (int value : phaseMarkerValues)
		{
			if (value > 0 && value <= maxHealth + 1)
			{
				if (markers == null)
				{
					markers = new float[PHASE_MARKER_VARBITS.length];
				}
				markers[count++] = markerFraction(value, maxHealth);
			}
		}
		phaseMarkers = markers == null ? BarState.NO_PHASE_MARKERS : Arrays.copyOf(markers, count);
		return phaseMarkers;
	}

	// Same placement as the game's own bar: a marker for value v sits at (v - 1) / max health.
	static float markerFraction(int value, int maxHealth)
	{
		return BarAnimation.clamp01((value - 1) / (float) maxHealth);
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.InteractingChanged;

@Slf4j
@Singleton
class OpponentTracker
{
	private final Client client;
	private final BossHealthBarConfig config;
	private final GameBossBar gameBossBar;
	private final TobBossBar tobBossBar;
	private final SuperiorTracker superiors;
	private final DamageTracker damage;

	@Getter(AccessLevel.PACKAGE)
	private Actor opponent;
	private long interactionLostMillis;

	@Setter(AccessLevel.PACKAGE)
	private Runnable onOpponentChanged = () ->
	{
	};

	private Actor knownBossActor;
	private String knownBossName;
	private boolean knownBoss;

	@Inject
	OpponentTracker(Client client, BossHealthBarConfig config, GameBossBar gameBossBar, TobBossBar tobBossBar,
		SuperiorTracker superiors, DamageTracker damage)
	{
		this.client = client;
		this.config = config;
		this.gameBossBar = gameBossBar;
		this.tobBossBar = tobBossBar;
		this.superiors = superiors;
		this.damage = damage;
	}

	void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() != client.getLocalPlayer())
		{
			return;
		}

		final Actor target = event.getTarget();
		if (target == null)
		{
			interactionLostMillis = System.currentTimeMillis();
			log.debug("Interaction lost with {}, will clear after {}s if not resumed", opponent, config.hideDelay());
			return;
		}

		interactionLostMillis = 0;

		if (target == opponent)
		{
			return;
		}

		// Attacking the smaller NPCs a boss spawns shouldn't take the bar off the boss.
		if (opponent != null && !opponent.isDead() && priority(target) < priority(opponent))
		{
			log.debug("Keeping {} over lower priority target {}", opponent.getName(), target.getName());
			return;
		}

		setOpponent(target);
	}

	// While a game boss bar is up, the bar follows the NPC it shows.
	void followGameBars()
	{
		final NPC nativeBarBoss = gameBossBar.findNpc(opponent);
		final NPC gameBarBoss = nativeBarBoss != null ? nativeBarBoss : tobBossBar.findBoss();
		if (gameBarBoss != null && !gameBarBoss.isDead() && gameBarBoss != opponent)
		{
			setOpponent(gameBarBoss);
			interactionLostMillis = 0;
		}
	}

	void onNpcDespawned(NPC npc)
	{
		if (npc != opponent)
		{
			return;
		}

		log.debug("Opponent {} despawned, clearing", opponent);
		opponent = null;
		interactionLostMillis = 0;
		damage.resetCombo();
	}

	// Clears the opponent once you've stopped interacting for longer than "Hide after", unless a
	// game boss bar still shows it.
	void onGameTick()
	{
		final Player player = client.getLocalPlayer();
		if (opponent != null
			&& player != null
			&& opponent != gameBossBar.findNpc(opponent)
			&& opponent != tobBossBar.findBoss()
			&& interactionLostMillis != 0
			&& player.getInteracting() == null
			&& System.currentTimeMillis() - interactionLostMillis > config.hideDelay() * 1000L)
		{
			log.debug("Opponent {} timed out after {}s with no interaction, clearing", opponent, config.hideDelay());
			opponent = null;
		}
	}

	boolean shouldShowBarFor(Actor actor)
	{
		return actor != null
			&& actor.getName() != null
			&& (!config.bossOnly()
				|| isKnownBoss(actor)
				|| isGameBarBoss(actor)
				|| (config.showAboveCombatLevel() && actor.getCombatLevel() >= config.minimumCombatLevel())
				|| (config.showSuperiors() && superiors.isSuperior(actor)));
	}

	void reset()
	{
		opponent = null;
		interactionLostMillis = 0;
		knownBossActor = null;
		knownBossName = null;
	}

	private void setOpponent(Actor target)
	{
		onOpponentChanged.run();
		damage.resetCombo();
		opponent = target;
		log.debug("New opponent: {} (combat level {}, known boss: {}, game boss bar: {})",
			target.getName(), target.getCombatLevel(), KnownBosses.contains(target.getName()), isGameBarBoss(target));
	}

	private int priority(Actor actor)
	{
		if (actor == null)
		{
			return -1;
		}
		if (gameBossBar.isTracking(actor) || tobBossBar.isTracking(actor))
		{
			return 2;
		}
		return shouldShowBarFor(actor) ? 1 : 0;
	}

	private boolean isGameBarBoss(Actor actor)
	{
		return actor != null && (gameBossBar.isTracking(actor) || actor == tobBossBar.cachedBoss());
	}

	// Checked every frame, so the answer is kept for the last actor and name.
	private boolean isKnownBoss(Actor actor)
	{
		final String name = actor.getName();
		if (actor != knownBossActor || !name.equals(knownBossName))
		{
			knownBossActor = actor;
			knownBossName = name;
			knownBoss = KnownBosses.contains(name);
		}
		return knownBoss;
	}
}

package com.ghordrin.bosshealthbar;

import java.time.Duration;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;

@Singleton
class DamageTracker
{
	static final Duration COMBO_WINDOW = Duration.ofMillis(2500);

	@Getter(AccessLevel.PACKAGE)
	private long lastHitMillis;

	@Getter(AccessLevel.PACKAGE)
	private int lastHitAmount;

	@Getter(AccessLevel.PACKAGE)
	private int comboDamage;

	@Getter(AccessLevel.PACKAGE)
	private long lastDamageDealtMillis;

	void recordHit(Hitsplat hitsplat)
	{
		if (hitsplat.getAmount() <= 0 || hitsplat.getHitsplatType() == HitsplatID.HEAL)
		{
			return;
		}

		final long now = System.currentTimeMillis();
		lastHitMillis = now;
		lastHitAmount = hitsplat.getAmount();

		if (hitsplat.isMine())
		{
			comboDamage = nextComboDamage(comboDamage, lastDamageDealtMillis, now, hitsplat.getAmount());
			lastDamageDealtMillis = now;
		}
	}

	void resetCombo()
	{
		comboDamage = 0;
		lastDamageDealtMillis = 0;
	}

	void reset()
	{
		lastHitMillis = 0;
		resetCombo();
	}

	static int nextComboDamage(int previousCombo, long previousDamageMillis, long now, int hitAmount)
	{
		final boolean withinWindow = previousDamageMillis != 0 && now - previousDamageMillis <= COMBO_WINDOW.toMillis();
		return (withinWindow ? previousCombo : 0) + hitAmount;
	}
}

package com.ghordrin.bosshealthbar;

public enum IntroAnimation
{
	FADE("Fade", false, false),
	SLIDE("Slide in", true, false),
	EXPAND("Expand", false, true),
	SLIDE_AND_EXPAND("Slide in and expand", true, true);

	private final String label;
	final boolean slide;
	final boolean expand;

	IntroAnimation(String label, boolean slide, boolean expand)
	{
		this.label = label;
		this.slide = slide;
		this.expand = expand;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Color;
import java.awt.Font;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.FontType;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BossHealthBarConfig.GROUP)
public interface BossHealthBarConfig extends Config
{
	String GROUP = "bosshealthbar";
	String HIDE_VANILLA_OVERLAY_KEY = "hideVanillaOverlay";
	String CUSTOM_ICON_ITEM_ID_KEY = "customIconItemId";
	String FILL_TEXTURE_ID_KEY = "fillTextureId";
	String CHOOSE_FILL_TEXTURE_KEY = "chooseFillTexture";
	String CHOOSE_CUSTOM_ICON_KEY = "chooseCustomIcon";
	String THEME_KEY = "theme";
	HealthBarTheme DEFAULT_THEME = HealthBarTheme.ZAMORAK;
	String FONT_KEY = "font";
	FontType DEFAULT_FONT = new FontType().withFamily(Font.SERIF).withSize(17);

	@ConfigSection(
		name = "Appearance",
		description = "How the bar looks and animates.",
		position = 0
	)
	String appearanceSection = "appearance";

	@ConfigSection(
		name = "Custom colors",
		description = "The colors used when Theme is set to Custom.",
		position = 1,
